這個改良版本採用相對游標定位（Relative Cursor Movement），不依賴易受終端滾動影響的 \E[6n 座標查詢，更加穩定且相容各大終端環境（macOS Terminal、Windows Terminal、iTerm2、Linux Console）。 #!/usr/bin/env bash # ============================================================================== # 互動式方向鍵選單函式 # 參數: 選項清單 (字串或陣列展開) # 返回: 使用者所選選項的索引值 (0, 1, 2...) # ============================================================================== select_option() { local -a options=("$@") local num_options=${#options[@]} # 如果沒有傳入任何選項，直接返回錯誤 [[ $num_options -eq 0 ]] && return 1 # ANSI 控制碼定義 local ESC=$'\033' local CURSOR_OFF="${ESC}[?25l" local CURSOR_ON="${ESC}[?25h" local CLEAR_LINE="${ESC}[2K" local TEXT_INVERT="${ESC}[7m" local TEXT_RESET="${ESC}[0m" # 捕獲中斷訊號 (Ctrl+C)，確保終端游標與屬性正常恢復 trap 'printf "${CURSOR_ON}"; stty echo; printf "
"; exit 130' INT TERM # 關閉游標閃爍 printf "%s" "${CURSOR_OFF}" local selected=0 # 首次渲染清單 local i for ((i=0; i<num_options; i++)); do if [[ $i -eq $selected ]]; then printf " ${TEXT_INVERT} > %s ${TEXT_RESET}
" "${options[i]}" else printf " %s 
" "${options[i]}" fi done # 監聽鍵盤輸入迴圈 while true; do # 讀取 3 個字元以捕獲方向鍵的轉義序列 (\033[A, \033[B) IFS= read -rsn1 key if [[ $key == "${ESC}" ]]; then read -rsn2 -t 0.1 rest key="${key}${rest}" fi case "$key" in "${ESC}[A"|k|K) # 向上鍵 (或 Vim 鍵位的 k) ((selected--)) [[ $selected -lt 0 ]] && selected=$((num_options - 1)) ;; "${ESC}[B"|j|J) # 向下鍵 (或 Vim 鍵位的 j) ((selected++)) [[ $selected -ge $num_options ]] && selected=0 ;; "") # Enter 鍵確認選擇 break ;; esac # 游標往上移回清單起點，重新覆寫整份選單 printf "${ESC}[%dA" "${num_options}" for ((i=0; i<num_options; i++)); do printf "${CLEAR_LINE}" if [[ $i -eq $selected ]]; then printf " ${TEXT_INVERT} > %s ${TEXT_RESET}
" "${options[i]}" else printf " %s 
" "${options[i]}" fi done done # 復原游標與環境 printf "%s" "${CURSOR_ON}" # 輸出選取的索引值 echo "$selected" }
